def attach_bank_questions(apps, schema_editor):
    """Раньше тест брал вопросы из банка по дисциплине и теме.
    Теперь у теста свой список: переносим туда те же вопросы."""
    Exam = apps.get_model("exams", "Exam")
    Question = apps.get_model("exams", "Question")
    for exam in Exam.objects.all():
        pool = Question.objects.filter(subject_id=exam.subject_id, is_active=True)
        topic = (exam.topic or "").strip().lower()
        ids = [q.id for q in pool if not topic or (q.topic or "").strip().lower() == topic]
        exam.questions.set(ids)


